CREATE TYPE public.app_role AS ENUM ('admin', 'coach');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, email text NOT NULL, first_name text NOT NULL DEFAULT '', last_name text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')), requested_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, decided_by uuid, reset_requested boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_or_admin_profiles ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_coach_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,first_name,last_name) VALUES(NEW.id,lower(NEW.email),left(coalesce(NEW.raw_user_meta_data->>'first_name',''),100),left(coalesce(NEW.raw_user_meta_data->>'last_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER coach_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_coach_profile();
CREATE FUNCTION public.assign_club_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='skiclubliberitutti@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; UPDATE public.profiles SET status='approved',decided_at=now() WHERE id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER club_owner_confirmed AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_club_owner();
CREATE TRIGGER club_owner_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_club_owner();
CREATE FUNCTION public.decide_coach_request(target_id uuid, decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Not authorized'; END IF; IF target_id=auth.uid() OR public.has_role(target_id,'admin') THEN RAISE EXCEPTION 'Cannot change owner access'; END IF; IF decision NOT IN ('approved','rejected','revoked') THEN RAISE EXCEPTION 'Invalid decision'; END IF; UPDATE public.profiles SET status=decision,decided_at=now(),decided_by=auth.uid() WHERE id=target_id; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.decide_coach_request(uuid,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.decide_coach_request(uuid,text) TO authenticated;
CREATE FUNCTION public.request_coach_reset() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.profiles SET reset_requested=true WHERE id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.request_coach_reset() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.request_coach_reset() TO authenticated;
REVOKE ALL ON FUNCTION public.create_coach_profile(), public.assign_club_owner() FROM PUBLIC, anon, authenticated;